function openCheck(moduleIndex) {
  const module = C[moduleIndex];
  const questions = moduleChecks[moduleIndex];
  const previous = state.checks[moduleIndex];
  const fields = questions.map(([prompt, options], index) => {
    const ordered = options.map((label, value) => ({label, value}));
    for (let i = ordered.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [ordered[i], ordered[j]] = [ordered[j], ordered[i]];
    }
    return '<fieldset><legend>'+esc(prompt)+'</legend>'+ordered.map(({label,value})=>'<label class="choice"><input type="radio" required name="q'+index+'" value="'+value+'">'+esc(label)+'</label>').join('')+'</fieldset>';
  }).join('');
  modal(dialogTop(module.name)+'<h2>Проверка модуля</h2><p>Ответьте по памяти. После проверки можно разобрать каждый ответ.</p>'+
    (previous?'<p class="muted">Последний результат: '+previous.score+' из 3.</p>':'')+
    '<form id="module-quiz">'+fields+'<button class="primary">Проверить ответы</button></form>');
  $('#module-quiz').onsubmit = event => {
    event.preventDefault();
    const form = new FormData(event.target);
    let score = 0;
    const feedback = questions.map(([prompt,options,why], j) => {
      const value = Number(form.get('q'+j));
      if (value === 0) score++;
      else state.reviews[moduleIndex+'-'+j] = {step:0,date:today()};
      return '<section class="feedback"><strong>'+(value===0?'✓ Верно':'Стоит повторить')+'</strong><h3>'+esc(prompt)+'</h3><p>Ваш ответ: '+esc(options[value])+'.</p>'+(value===0?'':'<p>Верный ответ: '+esc(options[0])+'.</p>')+'<p>'+esc(why)+'</p></section>';
    }).join('');
    state.checks[moduleIndex]={score,date:today()};
    touch();
    render();
    modal(dialogTop(module.name)+'<h2>Результат: '+score+' из 3</h2>'+(score<3?'<p>Уроки по ошибкам добавлены в повторение на сегодня.</p>':'<p>Все три ответа верны.</p>')+feedback+'<button class="primary" onclick="closeDialog()">К маршруту</button>');
  };
}
